#!/usr/bin/env node
// scripts/patch-android-overlay.mjs
//
// src-tauri/gen/ is gitignored and regenerated by `tauri android init`
// (locally via `npm run android:init` and in CI before every Android build),
// so the in-app AI overlay Kotlin sources live committed under
// src-tauri/android/ and are injected into the generated project by this
// script. It is idempotent — safe to run any number of times.

import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const genDir = join(root, 'src-tauri', 'gen', 'android');

if (!existsSync(genDir)) {
  console.log('[patch-android-overlay] gen/android belum ada — jalankan `npm run android:init` dulu (lewati).');
  process.exit(0);
}

// 1) Copy the overlay implementation into the generated app package.
const pkgDir = join(genDir, 'app', 'src', 'main', 'java', 'com', 'copastool', 'app');
mkdirSync(pkgDir, { recursive: true });
copyFileSync(join(root, 'src-tauri', 'android', 'AiOverlay.kt'), join(pkgDir, 'AiOverlay.kt'));
console.log('[patch-android-overlay] AiOverlay.kt tersalin ke gen/android.');

// 2) Hook it into MainActivity: attach the JS bridge to the main webview.
const mainActivityPath = join(pkgDir, 'MainActivity.kt');
if (!existsSync(mainActivityPath)) {
  console.log('[patch-android-overlay] MainActivity.kt tidak ditemukan — skip patch.');
  process.exit(0);
}
let src = readFileSync(mainActivityPath, 'utf8');

if (src.includes('CSTL-OVERLAY')) {
  console.log('[patch-android-overlay] MainActivity.kt sudah ter-patch (idempoten).');
} else {
  // Ensure the WebView import exists.
  if (!/^import android\.webkit\.WebView$/m.test(src)) {
    src = src.replace(/^import android\.os\.Bundle$/m, 'import android.os.Bundle\nimport android.webkit.WebView');
  }
  // Insert the override just before the final closing brace of the class.
  const hook = `
  // CSTL-OVERLAY — attach the in-app AI companion overlay bridge to the main webview
  override fun onWebViewCreate(webView: WebView) {
    super.onWebViewCreate(webView)
    AiOverlay.attach(this, webView)
  }
`;
  const lastBrace = src.lastIndexOf('}');
  if (lastBrace === -1) {
    console.error('[patch-android-overlay] Gagal mem-patch MainActivity.kt — closing brace tidak ditemukan.');
    process.exit(1);
  }
  src = src.slice(0, lastBrace) + hook + src.slice(lastBrace);
  writeFileSync(mainActivityPath, src);
  console.log('[patch-android-overlay] MainActivity.kt ter-patch.');
}

// 3) Lifecycle hook: keep Full Auto JS timers alive when backgrounded.
// WryActivity.onPause() freezes the main WebView; AiOverlay.onActivityPaused()
// immediately resumes it while background work is active. Separate marker so
// existing installs (already carrying CSTL-OVERLAY) pick this up too.
if (src.includes('CSTL-OVERLAY-BG')) {
  console.log('[patch-android-overlay] Lifecycle hook sudah ada (idempoten).');
} else {
  const bgHook = `
  // CSTL-OVERLAY-BG — keep Full Auto alive when the app is backgrounded
  override fun onPause() {
    super.onPause()
    AiOverlay.onActivityPaused()
  }
  override fun onResume() {
    super.onResume()
    AiOverlay.onActivityResumed()
  }
`;
  const lastBrace = src.lastIndexOf('}');
  if (lastBrace === -1) {
    console.error('[patch-android-overlay] Gagal mem-patch lifecycle — closing brace tidak ditemukan.');
    process.exit(1);
  }
  src = src.slice(0, lastBrace) + bgHook + src.slice(lastBrace);
  writeFileSync(mainActivityPath, src);
  console.log('[patch-android-overlay] Lifecycle hook ter-patch.');
}

// 4) Ensure ic_launcher_background color matches the icon theme (#241e47) instead of white (#fff)
const bgXmlPath = join(genDir, 'app', 'src', 'main', 'res', 'values', 'ic_launcher_background.xml');
if (existsSync(bgXmlPath)) {
  writeFileSync(bgXmlPath, '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n  <color name="ic_launcher_background">#241e47</color>\n</resources>\n');
  console.log('[patch-android-overlay] ic_launcher_background.xml ter-patch ke #241e47.');
}
